.anim-fade-in { opacity: 0; animation: fadeIn 400ms cubic-bezier(0.16, 1, 0.3, 1) forwards; }
@keyframes fadeIn { to { opacity: 1; } }
@media (prefers-reduced-motion: reduce) { .anim-fade-in { animation: none; opacity: 1; } }

.anim-fade-in-top { opacity: 0; transform: translateY(-16px); animation: fadeInTop 350ms cubic-bezier(0.16, 1, 0.3, 1) forwards; }
@keyframes fadeInTop { to { opacity: 1; transform: translateY(0); } }
@media (prefers-reduced-motion: reduce) { .anim-fade-in-top { animation: none; opacity: 1; transform: none; } }

.anim-fade-in-bottom { opacity: 0; transform: translateY(20px); animation: fadeInBottom 450ms cubic-bezier(0.16, 1, 0.3, 1) forwards; }
@keyframes fadeInBottom { to { opacity: 1; transform: translateY(0); } }
@media (prefers-reduced-motion: reduce) { .anim-fade-in-bottom { animation: none; opacity: 1; transform: none; } }

.anim-fade-in-left { opacity: 0; transform: translateX(-24px); animation: fadeInLeft 380ms cubic-bezier(0.16, 1, 0.3, 1) forwards; }
@keyframes fadeInLeft { to { opacity: 1; transform: translateX(0); } }
@media (prefers-reduced-motion: reduce) { .anim-fade-in-left { animation: none; opacity: 1; transform: none; } }

.anim-fade-in-right { opacity: 0; transform: translateX(24px); animation: fadeInRight 380ms cubic-bezier(0.16, 1, 0.3, 1) forwards; }
@keyframes fadeInRight { to { opacity: 1; transform: translateX(0); } }
@media (prefers-reduced-motion: reduce) { .anim-fade-in-right { animation: none; opacity: 1; transform: none; } }

.anim-scale-up { opacity: 0; transform: scale(0.92); animation: scaleUp 300ms cubic-bezier(0.16, 1, 0.3, 1) forwards; }
@keyframes scaleUp { to { opacity: 1; transform: scale(1); } }
@media (prefers-reduced-motion: reduce) { .anim-scale-up { animation: none; opacity: 1; transform: none; } }

.anim-scale-down { opacity: 0; transform: scale(1.08); animation: scaleDown 400ms cubic-bezier(0.16, 1, 0.3, 1) forwards; }
@keyframes scaleDown { to { opacity: 1; transform: scale(1); } }
@media (prefers-reduced-motion: reduce) { .anim-scale-down { animation: none; opacity: 1; transform: none; } }

.anim-zoom-fade { opacity: 0; transform: scale(0.75); animation: zoomFade 350ms cubic-bezier(0.34, 1.56, 0.64, 1) forwards; }
@keyframes zoomFade { to { opacity: 1; transform: scale(1); } }
@media (prefers-reduced-motion: reduce) { .anim-zoom-fade { animation: none; opacity: 1; transform: none; } }

.anim-blur-focus { opacity: 0; filter: blur(12px); animation: blurFocus 500ms ease-out forwards; }
@keyframes blurFocus { to { opacity: 1; filter: blur(0); } }
@media (prefers-reduced-motion: reduce) { .anim-blur-focus { animation: none; opacity: 1; filter: none; } }

.anim-flip-in { opacity: 0; transform: perspective(600px) rotateX(-45deg); animation: flipIn 450ms cubic-bezier(0.16, 1, 0.3, 1) forwards; }
@keyframes flipIn { to { opacity: 1; transform: perspective(600px) rotateX(0); } }
@media (prefers-reduced-motion: reduce) { .anim-flip-in { animation: none; opacity: 1; transform: none; } }

.anim-3d-rotate { opacity: 0; transform: perspective(800px) rotateY(25deg) scale(0.95); animation: rotate3dIn 500ms cubic-bezier(0.16, 1, 0.3, 1) forwards; }
@keyframes rotate3dIn { to { opacity: 1; transform: perspective(800px) rotateY(0) scale(1); } }
@media (prefers-reduced-motion: reduce) { .anim-3d-rotate { animation: none; opacity: 1; transform: none; } }

.anim-clip-reveal { clip-path: polygon(0 0, 0 0, 0 100%, 0 100%); animation: clipReveal 600ms cubic-bezier(0.77, 0, 0.175, 1) forwards; }
@keyframes clipReveal { to { clip-path: polygon(0 0, 100% 0, 100% 100%, 0 100%); } }
@media (prefers-reduced-motion: reduce) { .anim-clip-reveal { animation: none; clip-path: none; } }

.anim-fade-out { opacity: 1; animation: fadeOut 250ms ease-in forwards; }
@keyframes fadeOut { to { opacity: 0; pointer-events: none; } }
@media (prefers-reduced-motion: reduce) { .anim-fade-out { display: none; } }

.anim-slide-out-up { animation: slideOutUp 280ms cubic-bezier(0.7, 0, 0.84, 0) forwards; }
@keyframes slideOutUp { to { opacity: 0; transform: translateY(-20px); pointer-events: none; } }
@media (prefers-reduced-motion: reduce) { .anim-slide-out-up { display: none; } }

.anim-slide-out-down { animation: slideOutDown 280ms cubic-bezier(0.7, 0, 0.84, 0) forwards; }
@keyframes slideOutDown { to { opacity: 0; transform: translateY(24px); pointer-events: none; } }
@media (prefers-reduced-motion: reduce) { .anim-slide-out-down { display: none; } }

.anim-slide-out-left { animation: slideOutLeft 260ms ease-in forwards; }
@keyframes slideOutLeft { to { opacity: 0; transform: translateX(-30px); pointer-events: none; } }
@media (prefers-reduced-motion: reduce) { .anim-slide-out-left { display: none; } }

.anim-slide-out-right { animation: slideOutRight 260ms ease-in forwards; }
@keyframes slideOutRight { to { opacity: 0; transform: translateX(30px); pointer-events: none; } }
@media (prefers-reduced-motion: reduce) { .anim-slide-out-right { display: none; } }

.anim-scale-down-exit { animation: scaleDownExit 220ms ease-in forwards; }
@keyframes scaleDownExit { to { opacity: 0; transform: scale(0.8); pointer-events: none; } }
@media (prefers-reduced-motion: reduce) { .anim-scale-down-exit { display: none; } }

.anim-blur-fade-exit { animation: blurFadeExit 300ms ease-in forwards; }
@keyframes blurFadeExit { to { opacity: 0; filter: blur(10px); pointer-events: none; } }
@media (prefers-reduced-motion: reduce) { .anim-blur-fade-exit { display: none; } }

.anim-flip-exit { animation: flipExit 320ms cubic-bezier(0.7, 0, 0.84, 0) forwards; }
@keyframes flipExit { to { opacity: 0; transform: perspective(600px) rotateX(45deg); pointer-events: none; } }
@media (prefers-reduced-motion: reduce) { .anim-flip-exit { display: none; } }

.anim-lift-card { transform: translateY(0); transition: transform 240ms ease, box-shadow 240ms ease; }
.anim-lift-card:hover { transform: translateY(-5px); box-shadow: 0 12px 30px rgba(0,0,0,0.25); }
@media (prefers-reduced-motion: reduce) { .anim-lift-card:hover { transform: none; } }

.anim-scale-img { transition: transform 300ms cubic-bezier(0.16, 1, 0.3, 1); }
.anim-scale-img:hover { transform: scale(1.04); }
@media (prefers-reduced-motion: reduce) { .anim-scale-img:hover { transform: none; } }

.clipped-box { overflow: hidden; border-radius: 12px; }
.zoom-inner { transition: transform 400ms cubic-bezier(0.16, 1, 0.3, 1); display: block; width: 100%; }
.clipped-box:hover .zoom-inner { transform: scale(1.08); }
@media (prefers-reduced-motion: reduce) { .clipped-box:hover .zoom-inner { transform: none; } }

.anim-underline { position: relative; text-decoration: none; color: inherit; }
.anim-underline::after { content: ""; position: absolute; left: 0; bottom: -2px; width: 0; height: 2px; background: currentColor; transition: width 240ms ease; }
.anim-underline:hover::after { width: 100%; }

.anim-overlay-box { position: relative; overflow: hidden; }
.anim-overlay-box .overlay { position: absolute; inset: 0; background: rgba(0,0,0,0.4); transition: opacity 300ms ease; }
.anim-overlay-box:hover .overlay { opacity: 0; }

.anim-btn-ripple { position: relative; overflow: hidden; }
.ripple-effect { position: absolute; border-radius: 50%; transform: scale(0); animation: ripple 500ms linear; background: rgba(255,255,255,0.4); }
@keyframes ripple { to { transform: scale(4); opacity: 0; } }

.anim-btn-slide { position: relative; background: transparent; border: 2px solid var(--color-primary); color: var(--color-primary); z-index: 1; overflow: hidden; transition: color 250ms ease; }
.anim-btn-slide::before { content: ""; position: absolute; inset: 0; background: var(--color-primary); z-index: -1; transform: scaleX(0); transform-origin: left; transition: transform 250ms ease; }
.anim-btn-slide:hover { color: #fff; }
.anim-btn-slide:hover::before { transform: scaleX(1); }

.anim-switch input { opacity: 0; width: 0; height: 0; }
.slider { position: relative; display: inline-block; width: 44px; height: 24px; background: #334155; border-radius: 24px; transition: background 200ms ease; cursor: pointer; }
.slider::before { content: ""; position: absolute; height: 18px; width: 18px; left: 3px; bottom: 3px; background: #fff; border-radius: 50%; transition: transform 200ms ease; }
input:checked + .slider { background: #6366f1; }
input:checked + .slider::before { transform: translateX(20px); }

.anim-typewriter { overflow: hidden; white-space: nowrap; border-right: 2px solid var(--color-primary); animation: typing 3s steps(30, end), blink 750ms step-end infinite; }
@keyframes typing { from { width: 0; } to { width: 100%; } }
@keyframes blink { 50% { border-color: transparent; } }
@media (prefers-reduced-motion: reduce) { .anim-typewriter { animation: none; width: auto; border: none; } }

.word-reveal span { display: inline-block; opacity: 0; transform: translateY(10px); animation: wordIn 350ms forwards; }
.word-reveal span:nth-child(2) { animation-delay: 80ms; }
.word-reveal span:nth-child(3) { animation-delay: 160ms; }

.line-mask { overflow: hidden; }
.line-inner { transform: translateY(100%); animation: lineIn 500ms cubic-bezier(0.16, 1, 0.3, 1) forwards; }
@keyframes lineIn { to { transform: translateY(0); } }

.anim-grad-text { background: linear-gradient(90deg, #6366f1, #38bdf8, #ec4899, #6366f1); background-size: 300% 100%; -webkit-background-clip: text; -webkit-text-fill-color: transparent; animation: gradShift 4s linear infinite; }
@keyframes gradShift { 0% { background-position: 0% 0; } 100% { background-position: 300% 0; } }
@media (prefers-reduced-motion: reduce) { .anim-grad-text { animation: none; } }

.modal-backdrop { opacity: 0; backdrop-filter: blur(8px); transition: opacity 250ms ease; }
.modal-backdrop.open { opacity: 1; }
.modal-card { transform: scale(0.95); transition: transform 250ms ease; }
.modal-backdrop.open .modal-card { transform: scale(1); }

.flip-card { perspective: 800px; transform-style: preserve-3d; transition: transform 500ms ease; }
.flip-card.flipped { transform: rotateY(180deg); }
.flip-back { transform: rotateY(180deg); backface-visibility: hidden; }

.anim-grid .item { animation: gridPop 350ms ease forwards; }
.anim-grid .item:nth-child(2) { animation-delay: 50ms; }
.anim-grid .item:nth-child(3) { animation-delay: 100ms; }

.aurora-canvas { background: linear-gradient(135deg, #090a0f, #0f172a); position: relative; overflow: hidden; }
.aurora-canvas::after { content: ""; position: absolute; inset: -50%; background: radial-gradient(circle, rgba(16,185,129,0.15), rgba(139,92,246,0.15), transparent 70%); animation: auroraRotate 20s linear infinite; }
@keyframes auroraRotate { 100% { transform: rotate(360deg); } }

.bouncing-dots span { display: inline-block; width: 6px; height: 6px; background: currentColor; border-radius: 50%; animation: bounceDot 1.2s infinite ease-in-out both; margin: 0 2px; }
.bouncing-dots span:nth-child(1) { animation-delay: -0.32s; }
.bouncing-dots span:nth-child(2) { animation-delay: -0.16s; }
@keyframes bounceDot { 0%, 80%, 100% { transform: scale(0); } 40% { transform: scale(1); } }

.slide-bar { width: 100%; height: 3px; background: rgba(255,255,255,0.1); overflow: hidden; }
.slide-fill { width: 40%; height: 100%; background: var(--color-primary); animation: slideBar 1.2s infinite ease-in-out; }
@keyframes slideBar { 0% { transform: translateX(-100%); } 100% { transform: translateX(300%); } }

.progress-indeterminate { position: relative; height: 4px; overflow: hidden; background: #e2e8f0; }
.bar-line { position: absolute; height: 100%; background: var(--color-primary); animation: indet 1.5s cubic-bezier(0.65, 0.815, 0.735, 0.395) infinite; }
@keyframes indet { 0% { left: -35%; right: 100%; } 60% { left: 100%; right: -90%; } 100% { left: 100%; right: -90%; } }

.float-field { position: relative; }
.float-field label { position: absolute; left: 12px; top: 50%; transform: translateY(-50%); transition: all 200ms ease; pointer-events: none; color: #94a3b8; }
.float-field input:focus ~ label, .float-field input:not(:placeholder-shown) ~ label { top: 6px; font-size: 0.75rem; color: var(--color-primary); }

.step-view { transition: transform 300ms cubic-bezier(0.16, 1, 0.3, 1), opacity 300ms ease; }
.step-view.exit-left { transform: translateX(-100%); opacity: 0; }
.step-view.enter-right { transform: translateX(0); opacity: 1; }

.bar { display: block; width: 20px; height: 2px; background: currentColor; transition: all 250ms ease; margin: 4px 0; }
.menu-btn.open .top { transform: translateY(6px) rotate(45deg); }
.menu-btn.open .mid { opacity: 0; }
.menu-btn.open .bot { transform: translateY(-6px) rotate(-45deg); }

.status-dot { width: 8px; height: 8px; border-radius: 50%; background: #10b981; position: relative; }
.status-dot::after { content: ""; position: absolute; inset: -4px; border: 2px solid #10b981; border-radius: 50%; animation: ping 2s cubic-bezier(0, 0, 0.2, 1) infinite; }
@keyframes ping { 75%, 100% { transform: scale(2); opacity: 0; } }

.glitch-text { position: relative; }
.glitch-text::before, .glitch-text::after { content: attr(data-text); position: absolute; top: 0; left: 0; clip: rect(0, 0, 0, 0); }
.glitch-text:hover::before { left: -2px; text-shadow: 2px 0 red; animation: glitch1 400ms infinite linear alternate-reverse; }
